WITH valid AS (SELECT id, email, dept_id, manager_id, job_title, salary, is_remote, DATE_SUB(hire_date, 29) AS hire_date_minus_29d FROM employees WHERE hire_date > DATE '2023-06-24' AND manager_id IS NOT NULL AND job_title IN ('Manager', 'Engineer', 'Director')) SELECT id, email, dept_id, manager_id, job_title, salary, is_remote, hire_date_minus_29d, MIN(salary) OVER (PARTITION BY manager_id, job_title) AS manager_id_min_salary, FIRST_VALUE(job_title) IGNORE NULLS OVER (PARTITION BY dept_id ORDER BY salary ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_job_title FROM valid
